import { existsSync } from "node:fs";
import { mkdir, readdir, writeFile } from "node:fs/promises";
import { basename, dirname, extname, join, resolve } from "node:path";
import { teamsCredentialEnv } from "../channels/teams/credentials.js";
import { CliError } from "./cli/errors.js";
import { credentialEnvNameError } from "./credential-env-names.js";
import { isAgentProjectDir, loadAgentProject } from "./discovery.js";
import { readSecretValue } from "./cli-deploy.js";
import { CLOUDFLARED_INSTALL_URL } from "./cli-teams-forward.js";
import { CLI_COMMAND_NAME as CLI, PACKAGE_NAME } from "./distribution.js";
import { ensureEnvLocalGitignored, upsertEnvFile } from "./env-file.js";
import { isGuid } from "./guid.js";
import { projectPath, resolveProjectRoot } from "./project-layout.js";
import { envKeyList, teamsChannelProfiles, } from "./teams-channel-profile.js";
const TEAMS = `${CLI} channels teams`;
const TEAMS_SETUP_PHASES = [
    {
        actor: "human",
        title: "Create the Azure Bot",
        steps: [
            "In the Azure portal, select Create a resource, then Azure Bot.",
            "Set Type of App to Single Tenant. Teams doctor fails on any other type.",
            "Set Creation type to Create new Microsoft App ID.",
            "On Configuration, copy the Microsoft App ID and the App Tenant ID.",
            "On Configuration, select Manage Password, then New client secret. Copy the secret value.",
        ],
    },
    {
        actor: "human",
        title: "Turn on the Teams channel",
        steps: ["On the Azure Bot, open Channels, select Microsoft Teams, then select Apply."],
    },
    {
        actor: "agent",
        title: "Write the credentials",
        steps: [
            `${TEAMS} init --dir . --app-id <id> --tenant-id <id>`,
            "Type the client secret at the hidden prompt, or pipe it on stdin.",
        ],
    },
    {
        actor: "agent",
        title: "Build the Teams app",
        steps: [
            `${TEAMS} package --dir .`,
            "It writes <slug>-teams-app.zip: the bot's app id, the chats the channel answers in, and a new version on each run.",
        ],
    },
    {
        actor: "agent",
        title: "Serve and open a tunnel",
        steps: [
            `${CLI} dev .`,
            "It opens a cloudflared quick tunnel and prints the messaging endpoint. Set it on the Azure Bot: Configuration, Messaging endpoint, Apply.",
            `cloudflared must be on PATH: ${CLOUDFLARED_INSTALL_URL}`,
            `The cloudflared URL changes each time \`${CLI} dev\` starts. For one URL, run \`${CLI} dev . --tunnel devtunnel\` after \`devtunnel user login\`.`,
            `Next to a plain \`${CLI} serve\`, \`${TEAMS} forward --dir .\` opens the tunnel.`,
        ],
    },
    {
        actor: "agent",
        title: "Check every part",
        steps: [
            `${TEAMS} doctor --dir . --endpoint <printed URL>`,
            "It checks the env names, the token, and the endpoint. When az is logged in, it also checks the bot's tenant, its messaging endpoint, and its Teams channel.",
        ],
    },
    {
        actor: "human",
        title: "Install and smoke test",
        steps: [
            "In Teams, open Apps, Manage your apps, Upload an app, and choose the zip. A Teams admin can publish it to the organization from the Teams admin center.",
            "Add the app to a team, a group chat, or a personal chat.",
            "@mention the bot or send it a message.",
        ],
    },
];
export function formatTeamsSetupGuide() {
    const keys = teamsCredentialEnv("PREFIX").keys;
    const lines = [
        `${CLI} — Microsoft Teams setup`,
        "",
        "This pack connects your own Azure Bot. You bring its app id, client secret, and tenant id.",
        `Teams has no Socket Mode. Local dev needs a public HTTPS endpoint, and \`${CLI} dev\` opens one.`,
        "",
    ];
    for (const [index, phase] of TEAMS_SETUP_PHASES.entries()) {
        lines.push(`## Phase ${index + 1} — ${phase.title} (${phase.actor})`);
        for (const step of phase.steps) {
            lines.push(`  - ${step}`);
        }
        lines.push("");
    }
    lines.push(`Env: ${envKeyList(teamsCredentialEnv().keys).join(", ")}. With \`init --prefix PREFIX\`: ${envKeyList(keys).join(", ")}. A kept channel file keeps its own names. \`doctor\` and \`package\` read the names the channel declares.`, "Docs: https://cursor.com/docs/agent-sdk/reference/cli#teams", "");
    return lines.join("\n");
}
function parseGuid(input) {
    const value = input.value?.trim();
    if (value === undefined || value === "") {
        throw new CliError(`--${input.flag} is required. Pass the ${input.label} of the Azure Bot.`, {
            code: "invalid_argument",
            hint: "Copy it from the Azure Bot's Configuration page.",
        });
    }
    if (!isGuid(value)) {
        throw new CliError(`--${input.flag} must be a GUID such as 00000000-0000-0000-0000-000000000000.`, {
            code: "invalid_argument",
            hint: `Copy the ${input.label} from the Azure Bot's Configuration page. The client secret goes to the hidden prompt or stdin.`,
        });
    }
    return value;
}
function teamsChannelSource(env) {
    const config = env.envPrefix === "" ? "" : `{\n  envPrefix: ${JSON.stringify(env.envPrefix)},\n}`;
    return `import { teamsChannel } from "${PACKAGE_NAME}/channels/teams";

/**
 * Microsoft Teams channel (Azure Bot).
 *
 * Credentials: ${envKeyList(env.keys).join(", ")}
 *
 * Setup: ${TEAMS} setup
 */
export default teamsChannel(${config});
`;
}
function assertPrefixFlag(prefix) {
    if (prefix !== undefined && prefix.trim() !== "" && teamsCredentialEnv(prefix).envPrefix === "") {
        throw new CliError(`--prefix ${JSON.stringify(prefix)} has no letters or digits.`, {
            code: "invalid_argument",
            hint: "Pass a prefix such as HELM, or leave --prefix out for the TEAMS_* names.",
        });
    }
}
function assertEnvPrefix(env, channelId) {
    const nameError = credentialEnvNameError(channelId, env);
    if (nameError !== undefined) {
        throw new CliError(nameError, { code: "invalid_argument" });
    }
}
/** Every Teams channel the project already has, under any file name. */
async function existingTeamsChannels(dir) {
    if (!(await isAgentProjectDir(dir))) {
        return [];
    }
    return teamsChannelProfiles([{ slug: "", project: await loadAgentProject(dir) }]);
}
async function channelFilePath(dir, channelId) {
    const root = resolveProjectRoot(dir);
    const files = await readdir(join(dir, root, "channels")).catch(() => []);
    const file = files.find((name) => basename(name, extname(name)) === channelId);
    return projectPath(root, `channels/${file ?? channelId}`);
}
/** A kept channel file owns its env names; init writes those names and never guesses. */
function keptCredentialEnv({ profile, channelPath, prefix, }) {
    const env = profile.credentialEnv;
    if (env === undefined) {
        throw new CliError(`${channelPath} sets its credentials in code, so init has no env names to write.`, { code: "failed_precondition", hint: `Set the credentials where ${channelPath} reads them.` });
    }
    if (prefix !== undefined && teamsCredentialEnv(prefix).envPrefix !== env.envPrefix) {
        throw new CliError(`${channelPath} reads ${env.keys.appId}, so --prefix ${prefix} would write names the channel does not read.`, { code: "invalid_argument", hint: `Drop --prefix, or change envPrefix in ${channelPath}.` });
    }
    assertEnvPrefix(env, profile.channelId);
    return env;
}
export async function cmdTeamsInit(options) {
    const appId = parseGuid({ flag: "app-id", label: "Microsoft App ID", value: options.appId });
    const tenantId = parseGuid({
        flag: "tenant-id",
        label: "App Tenant ID",
        value: options.tenantId,
    });
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    assertPrefixFlag(options.prefix);
    const dir = resolve(options.dir);
    const existing = await existingTeamsChannels(dir);
    if (existing.length > 1) {
        throw new CliError(`the project already has ${existing.length} Teams channels (${existing.map((channel) => channel.channelId).join(", ")}), so init cannot pick one.`, { code: "failed_precondition", hint: "Set each channel's credentials in .env.local." });
    }
    const kept = existing[0];
    const channelAction = kept === undefined ? "created" : "kept";
    const channelPath = kept === undefined
        ? projectPath(resolveProjectRoot(dir), "channels/teams.ts")
        : await channelFilePath(dir, kept.channelId);
    if (kept === undefined && existsSync(join(dir, channelPath))) {
        throw new CliError(`${channelPath} exists but is not a Teams channel the CLI can load.`, {
            code: "failed_precondition",
            hint: `Make it export teamsChannel() from ${PACKAGE_NAME}/channels/teams, or move it.`,
        });
    }
    let credentialEnv;
    if (kept !== undefined) {
        credentialEnv = keptCredentialEnv({ profile: kept, channelPath, prefix: options.prefix });
    }
    else {
        credentialEnv = teamsCredentialEnv(options.prefix);
        assertEnvPrefix(credentialEnv, "teams");
    }
    const envKeys = credentialEnv.keys;
    const dryRun = options.dryRun === true;
    if (!dryRun) {
        const appPassword = (await readSecretValue(options.stdin ?? process.stdin, err, envKeys.appPassword)).trim();
        if (appPassword === "") {
            throw new CliError(`the client secret for ${envKeys.appPassword} is empty.`, {
                code: "invalid_argument",
            });
        }
        if (channelAction === "created") {
            await mkdir(dirname(join(dir, channelPath)), { recursive: true });
            await writeFile(join(dir, channelPath), teamsChannelSource(credentialEnv), {
                flag: "wx",
            });
        }
        await upsertEnvFile(join(dir, ".env.local"), [
            { key: envKeys.appId, value: appId },
            { key: envKeys.appPassword, value: appPassword },
            { key: envKeys.tenantId, value: tenantId },
        ]);
        await ensureEnvLocalGitignored(dir);
    }
    const next = [`${TEAMS} doctor --dir ${options.dir}`, `${CLI} dev ${options.dir}`];
    if (options.json === true) {
        const result = {
            ok: true,
            dryRun,
            directory: dir,
            channelFile: { path: channelPath, action: channelAction },
            envFile: ".env.local",
            envPrefix: credentialEnv.envPrefix,
            envKeys,
            next,
        };
        out(`${JSON.stringify(result, null, 2)}\n`);
        return 0;
    }
    const keyNames = envKeyList(envKeys).join(", ");
    const lines = dryRun
        ? [
            "Dry run. Nothing written.",
            `Would ${channelAction === "created" ? "create" : "keep"} ${channelPath}`,
            `Would set ${keyNames} in .env.local`,
        ]
        : [
            `${channelAction === "created" ? "Created" : "Kept"} ${channelPath}`,
            `Set ${keyNames} in .env.local`,
            "",
            "Next:",
            ...next.map((step) => `  ${step}`),
        ];
    out(`${lines.join("\n")}\n`);
    return 0;
}
